      final harness = await FaCliHarness.spawn(
        workingDirectory: project.path,
        extraEnv: env(),
        args: ['--session', 'pty539-frames-$columns'],
        columns: columns,
        rows: rows,
      );
      addTearDown(harness.close);

      await harness.waitForBoot();
