      );
      await harness.waitForText(
        _replyOne,
        timeout: const Duration(seconds: 60),
      );
      await harness.waitForOutput(settleMs: 400);

      // ── wave two: the first bucket ages out while still live ─────────
      harness.sendText('run wave two');
      harness.sendEnter();
