  /// stamped by the board.
  void start(TaskBlock card) {
    _cards.add(
      TaskBlock(
        id: card.id,
        kind: card.kind,
        label: card.label,
        state: card.state == TaskBlockState.running
            ? TaskBlockState.running
            : TaskBlockState.lost,
        elapsed: card.elapsed,
        exitCode: card.exitCode,
        detail: card.detail,
        turn: turn,
